def transform(grid):
    # Identify the long thin L-shaped color guide, then recolor the nearest
    # distinct connected object with the guide's color.
    h, w = len(grid), len(grid[0])
    guides = []
    for color in set(v for row in grid for v in row):
        if color == 9:
            continue
        for obj in components(grid, color):
            rows = [r for r, c in obj]
            cols = [c for r, c in obj]
            height, width = max(rows)-min(rows)+1, max(cols)-min(cols)+1
            # Long, thin components are candidate strokes/guides.
            if len(obj) >= 6 and (height >= 3 or width >= 3):
                guides.append((len(obj), color, obj))
    if not guides:
        return [row[:] for row in grid]
    _, color, guide = max(guides)
    # The guide corner is its cell with the greatest local degree (the L bend).
    def degree(cell):
        r, c = cell
        return sum((r+dr, c+dc) in guide for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)))
    corner = max(guide, key=lambda p: (degree(p), p[0], p[1]))
    others = []
    for other_color in set(v for row in grid for v in row):
        if other_color in (9, color):
            continue
        for obj in components(grid, other_color):
            dist = min(abs(r-corner[0])+abs(c-corner[1]) for r,c in obj)
            others.append((dist, len(obj), other_color, obj))
    if not others:
        return [row[:] for row in grid]
    _, _, _, target = min(others, key=lambda x: (x[0], -x[1]))
    out = [row[:] for row in grid]
    for r, c in target:
        out[r][c] = color
    return out


