                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == color and (yy, xx) not in seen:
                        seen.add((yy, xx))
                        q.append((yy, xx))
            result.append(obj)
    return result


def structure(obj):
    """Return whether the component is an exact L or a solid rectangle."""
    rs, cs = [r for r, c in obj], [c for r, c in obj]
    r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
    rectangle = {(r, c) for r in range(r0, r1+1) for c in range(c0, c1+1)}
    if obj == rectangle:
        return ('rectangle', None)
    for r in range(r0, r1+1):
        for c in range(c0, c1+1):
            horizontal = {(r, x) for x in range(c0, c1+1)}
            vertical = {(y, c) for y in range(r0, r1+1)}
            if len(horizontal) >= 2 and len(vertical) >= 2 and obj == horizontal | vertical:
                return ('L', (r, c))
    return (None, None)


def transform(grid):
    out = [row[:] for row in grid]
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    objects = []
    for color in set(counts) - {background}:
        for obj in components(grid, color):
            kind, corner = structure(obj)
            objects.append((color, obj, kind, corner))
    guides = [x for x in objects if x[2] == 'L']
    if not guides:
        return out
    # The guide's L bend points toward the nearest other non-background motif.
    # Among equally near motifs, prefer a solid rectangle (the demos show the
    # target is often a block); otherwise choose the larger component.
    _, _, _, corner = max(guides, key=lambda x: len(x[1]))
    target_candidates = []
    guide_color = max(guides, key=lambda x: len(x[1]))[0]
    for color, obj, kind, _ in objects:
        if kind == 'L':
            continue
        distance = min(abs(r-corner[0]) + abs(c-corner[1]) for r, c in obj)
        target_candidates.append((distance, 0 if kind == 'rectangle' else 1, -len(obj), color, obj))
    if target_candidates:
        _, _, _, _, target = min(target_candidates)
        for r, c in target:
            out[r][c] = guide_color
    return out


