def components(grid, color):
    h, w = len(grid), len(grid[0])
    seen, result = set(), []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != color or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            obj = set()
            while q:
                y, x = q.popleft()
                obj.add((y, x))
                for yy, xx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == color and (yy, xx) not in seen:
                        seen.add((yy, xx))
                        q.append((yy, xx))
            result.append(obj)
    return result


def find_l(obj):
    rs, cs = [r for r, c in obj], [c for r, c in obj]
    r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
    for r in range(r0, r1+1):
        for c in range(c0, c1+1):
            horizontal = {(r, x) for x in range(c0, c1+1)}
            vertical = {(y, c) for y in range(r0, r1+1)}
            if len(horizontal) >= 2 and len(vertical) >= 2 and obj == horizontal | vertical:
                return r, c, (r0, r1, c0, c1)
    return None


def transform(grid):
    out = [row[:] for row in grid]
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    guides = []
    for color in set(counts) - {bg}:
        for obj in components(grid, color):
            info = find_l(obj)
            if info:
                r, c, bounds = info
                guides.append((len(obj), color, obj, r, c, bounds))
    if not guides:
        return out
    _, guide_color, guide, r, c, (r0, r1, c0, c1) = max(guides)

    # The guide's open quadrant is the side opposite its two strokes.
    horizontal_dir = -1 if c == c1 else 1
    vertical_dir = -1 if r == r1 else 1
    candidates = []
    for color in set(counts) - {bg, guide_color}:
        for obj in components(grid, color):
            if obj & guide:
                continue
            # Restrict selection to objects in the quadrant opened by the L.
            qualifies = any((rr-r) * vertical_dir < 0 and (cc-c) * horizontal_dir < 0 for rr, cc in obj)
            if not qualifies:
                continue
            distance = min(abs(rr-r) + abs(cc-c) for rr, cc in obj)
            candidates.append((distance, -len(obj), color, obj))
    if candidates:
        target = min(candidates, key=lambda x: (x[0], x[1]))[3]
        for rr, cc in target:
